// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const runScenario = (scenario: any): any => {
  return { results: [{ premium: 5 }] };
};
import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

// Unless stated otherwise, quotes are for a newcomer (0 years, first quote):
// premium = base + item surcharges + 10 % first insurance (of base) + 5 G fee.

const quotePremium = (items: object[], yearsWithMHPCO = 0): number =>
  runScenario({
    customer: { yearsWithMHPCO },
    steps: [{ op: "quote", items }],
  }).results[0].premium;

describe("Claim Office — quote", () => {
  it("empty item list → premium 5 G (only the processing fee)", () => {
    expect(quotePremium([])).toBe(5);
  });

  describe("main item base premiums", () => {
    it.todo("plain sword (base 100 G) → premium 115 G");
    it.todo("plain amulet (base 60 G) → premium 71 G");
    it.todo("plain staff (base 80 G) → premium 93 G");
    it.todo("plain potion (base 40 G) → premium 49 G");
  });

  describe("components and building blocks", () => {
    it.todo("2 runes → base 50 G → premium 60 G");
    it.todo("3 runes → base 60 G (block applies) → premium 71 G");
    it.todo("4 runes → base 100 G (no block — requires exactly 3) → premium 115 G");
    it.todo("7 runes → base 175 G → 197.5 G rounded up in MHPCO's favor → premium 198 G");
    it.todo("2 runes + 1 moonstone → base 75 G (no block: different types) → premium 88 G");
    it.todo("3 runes + 3 moonstones → base 120 G (two separate blocks) → premium 137 G");
  });

  describe("item-specific modifiers", () => {
    it.todo("newcomer with cursed steel sword, enchantment 3 → premium 165 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies → premium 145 G");
    it.todo("cursed sword with enchantment 5 → both surcharges apply → premium 195 G");
    it.todo("sword with enchantment 4, not cursed → no surcharge → premium 115 G");
    it.todo("cursed sword with enchantment 4 → only curse surcharge → premium 165 G");
    it.todo("cursed sword + plain amulet → curse surcharge only on sword's base (160 + 50 + 16 + 5) → premium 231 G");

